export default {"fps": 30, "width": 1920, "height": 1080, "total": 317.474, "audio": "estimated", "chapters": [{"id": 1, "name": "第一章", "title": "山河危局", "start": 0.0}, {"id": 2, "name": "第二章", "title": "救亡图存", "start": 30.3}, {"id": 3, "name": "第三章", "title": "维新登场", "start": 88.198}, {"id": 4, "name": "第四章", "title": "百日新政", "start": 136.889}, {"id": 5, "name": "第五章", "title": "风暴将至", "start": 197.352}, {"id": 6, "name": "第六章", "title": "戊戌政变", "start": 242.065}, {"id": 7, "name": "第七章", "title": "历史回响", "start": 284.397}], "scenes": [{"id": "S01_war_map", "chapter": 1, "start": 0.0, "dur": 10.445, "cues": [{"text": "1894年，中日甲午战争爆发", "start": 2.4, "end": 5.003, "line": 0}, {"text": "次年，北洋舰队全军覆没", "start": 5.463, "end": 7.5, "line": 1}, {"text": "清政府被迫签订《马关条约》", "start": 7.66, "end": 9.885, "line": 1}]}, {"id": "S02_treaty", "chapter": 1, "start": 10.445, "dur": 4.663, "cues": [{"text": "割让台湾、澎湖，赔款白银二亿两", "start": 0.2, "end": 2.803, "line": 0}]}, {"id": "S03_hook", "chapter": 1, "start": 15.108, "dur": 8.192, "cues": [{"text": "1898年，一场试图改变中国命运的改革", "start": 0.5, "end": 4.046, "line": 0}, {"text": "为何只持续了103天？", "start": 4.306, "end": 6.532, "line": 1}]}, {"id": "S04_title", "chapter": 1, "start": 23.3, "dur": 7.0, "cues": []}, {"id": "S05_old_city", "chapter": 2, "start": 30.3, "dur": 9.002, "cues": [{"text": "甲午之败，震动朝野", "start": 1.6, "end": 3.259, "line": 0}, {"text": "泱泱大国败于东邻日本", "start": 3.719, "end": 5.756, "line": 1}, {"text": "“天朝上国”的迷梦就此破碎", "start": 5.916, "end": 8.141, "line": 1}]}, {"id": "S06_partition", "chapter": 2, "start": 39.301, "dur": 11.997, "cues": [{"text": "列强随即掀起瓜分中国的狂潮", "start": 0.4, "end": 3.003, "line": 0}, {"text": "1897年，德国强占胶州湾", "start": 3.263, "end": 5.677, "line": 1}, {"text": "次年，俄国强租旅顺、大连", "start": 5.937, "end": 7.974, "line": 2}, {"text": "英、法等国也纷纷划分势力范围", "start": 8.134, "end": 10.737, "line": 2}]}, {"id": "S07_jiuwang", "chapter": 2, "start": 51.298, "dur": 5.605, "cues": [{"text": "民族危机空前深重", "start": 0.3, "end": 1.959, "line": 0}, {"text": "“救亡图存”成为时代的呼声", "start": 2.119, "end": 4.345, "line": 0}]}, {"id": "S08_gongche", "chapter": 2, "start": 56.903, "dur": 15.67, "cues": [{"text": "1895年春，康有为联合在京参加会试的举人，起草上书", "start": 0.3, "end": 4.978, "line": 0}, {"text": "主张拒和、迁都、练兵、变法，史称“公车上书”", "start": 5.238, "end": 8.407, "line": 1}, {"text": "不过，关于参与人数和上书是否真正递交", "start": 8.867, "end": 12.225, "line": 2}, {"text": "史学界至今仍有不同看法", "start": 12.385, "end": 14.61, "line": 2}]}, {"id": "S09_press", "chapter": 2, "start": 72.573, "dur": 15.625, "cues": [{"text": "此后，维新人士纷纷组织学会、创办报刊", "start": 0.3, "end": 3.469, "line": 0}, {"text": "梁启超在上海主笔《时务报》", "start": 3.729, "end": 5.954, "line": 1}, {"text": "严复在天津参与创办《国闻报》，译述《天演论》", "start": 6.114, "end": 9.472, "line": 1}, {"text": "“变法”二字，从士大夫的书斋", "start": 9.932, "end": 12.157, "line": 2}, {"text": "走向了更广阔的社会", "start": 12.317, "end": 14.165, "line": 2}]}, {"id": "S10_reformers", "chapter": 3, "start": 88.198, "dur": 20.509, "cues": [{"text": "维新运动的核心人物", "start": 1.6, "end": 3.449, "line": 0}, {"text": "是康有为、梁启超和谭嗣同", "start": 3.609, "end": 5.834, "line": 0}, {"text": "康有为著《新学伪经考》《孔子改制考》，借孔子之名，为变法立论", "start": 6.294, "end": 10.972, "line": 1}, {"text": "他的学生梁启超，以一支健笔", "start": 11.232, "end": 13.647, "line": 2}, {"text": "让变法主张传遍全国", "start": 13.807, "end": 15.655, "line": 2}, {"text": "谭嗣同著《仁学》，猛烈抨击束缚人心的纲常名教", "start": 15.915, "end": 19.65, "line": 3}]}, {"id": "S11_guangxu", "chapter": 3, "start": 108.708, "dur": 5.305, "cues": [{"text": "而真正把变法推上朝堂的", "start": 0.3, "end": 2.525, "line": 0}, {"text": "是年轻的光绪皇帝", "start": 2.685, "end": 4.344, "line": 0}]}, {"id": "S12_palace", "chapter": 3, "start": 114.012, "dur": 7.248, "cues": [{"text": "1898年6月11日", "start": 1.2, "end": 3.237, "line": 0}, {"text": "光绪帝颁布《明定国是诏》，宣布变法", "start": 3.397, "end": 6.189, "line": 0}]}, {"id": "S13_edict", "chapter": 3, "start": 121.261, "dur": 7.448, "cues": [{"text": "诏书要求在坚守圣贤义理的同时", "start": 0.6, "end": 3.391, "line": 0}, {"text": "“博采西学之切于时务者”", "start": 3.551, "end": 5.588, "line": 0}]}, {"id": "S14_timeline", "chapter": 3, "start": 128.709, "dur": 8.18, "cues": [{"text": "五天后，光绪帝在颐和园召见康有为", "start": 0.3, "end": 3.28, "line": 0}, {"text": "一场自上而下的变革，就此拉开序幕", "start": 3.74, "end": 6.72, "line": 1}]}, {"id": "S15_edicts", "chapter": 4, "start": 136.889, "dur": 7.071, "cues": [{"text": "此后的一百多天里", "start": 1.6, "end": 3.26, "line": 0}, {"text": "光绪帝接连颁布上百道新政诏令", "start": 3.42, "end": 6.211, "line": 0}]}, {"id": "S16_politics", "chapter": 4, "start": 143.96, "dur": 8.901, "cues": [{"text": "政治上，裁撤詹事府、通政司等闲散衙门，裁汰冗员", "start": 0.3, "end": 4.224, "line": 0}, {"text": "允许各级官员和士民上书言事，疏通言路", "start": 4.484, "end": 7.842, "line": 1}]}, {"id": "S17_education", "chapter": 4, "start": 152.862, "dur": 15.425, "cues": [{"text": "教育上，废除八股取士", "start": 0.3, "end": 2.148, "line": 0}, {"text": "乡试、会试改试策论", "start": 2.308, "end": 3.967, "line": 0}, {"text": "需要强调的是，这并不是废除科举", "start": 4.427, "end": 7.219, "line": 1}, {"text": "——科举制度直到1905年才被正式废止", "start": 7.379, "end": 10.736, "line": 1}, {"text": "各地书院，则改为兼习中学、西学的学堂", "start": 11.196, "end": 14.365, "line": 2}]}, {"id": "S18_university", "chapter": 4, "start": 168.287, "dur": 15.803, "cues": [{"text": "这一时期创办的京师大学堂", "start": 0.4, "end": 2.814, "line": 0}, {"text": "既是全国最高学府", "start": 2.974, "end": 4.634, "line": 0}, {"text": "也是统辖各省学堂的教育行政机关", "start": 4.794, "end": 7.774, "line": 0}, {"text": "政变之后，它作为少数保留下来的新政成果继续开办", "start": 8.234, "end": 12.535, "line": 1}, {"text": "后来发展为北京大学", "start": 12.695, "end": 14.543, "line": 1}]}, {"id": "S19_economy", "chapter": 4, "start": 184.09, "dur": 6.914, "cues": [{"text": "经济上，设立农工商总局和矿务铁路总局，提倡实业", "start": 0.3, "end": 4.412, "line": 0}, {"text": "奖励发明创造", "start": 4.572, "end": 5.854, "line": 0}]}, {"id": "S20_military", "chapter": 4, "start": 191.004, "dur": 6.348, "cues": [{"text": "军事上，裁减旧式军队，改练洋操", "start": 0.3, "end": 2.903, "line": 0}, {"text": "倡导以西法训练新式军队", "start": 3.063, "end": 5.288, "line": 0}]}, {"id": "S22_resistance", "chapter": 5, "start": 197.352, "dur": 20.453, "cues": [{"text": "然而，变法的阻力从一开始就存在", "start": 1.6, "end": 4.392, "line": 0}, {"text": "诏令雪片般下达", "start": 4.852, "end": 6.323, "line": 1}, {"text": "许多地方督抚却观望拖延", "start": 6.483, "end": 8.708, "line": 1}, {"text": "裁撤衙门、改革科举", "start": 8.968, "end": 10.628, "line": 2}, {"text": "又触动了大批官员和读书人的切身利益", "start": 10.788, "end": 14.145, "line": 2}, {"text": "新政推行仓促，官僚体系执行乏力", "start": 14.605, "end": 17.397, "line": 3}, {"text": "许多措施停留在纸面上", "start": 17.557, "end": 19.593, "line": 3}]}, {"id": "S23_power", "chapter": 5, "start": 217.805, "dur": 13.516, "cues": [{"text": "更关键的是，光绪帝并未掌握实权", "start": 0.3, "end": 3.092, "line": 0}, {"text": "变法开始仅四天", "start": 3.552, "end": 5.023, "line": 1}, {"text": "帝师翁同龢便被开缺回籍", "start": 5.183, "end": 7.408, "line": 1}, {"text": "慈禧太后的亲信荣禄出任直隶总督", "start": 7.568, "end": 10.548, "line": 1}, {"text": "掌握京畿一带的兵权", "start": 10.708, "end": 12.557, "line": 1}]}, {"id": "S24_corridor", "chapter": 5, "start": 231.322, "dur": 10.743, "cues": [{"text": "9月初，光绪帝罢免阻挠上书的礼部六堂官", "start": 0.4, "end": 3.946, "line": 0}, {"text": "又任命谭嗣同等四人为军机章京", "start": 4.106, "end": 6.897, "line": 0}, {"text": "帝后之间的矛盾迅速激化", "start": 7.057, "end": 9.283, "line": 0}]}, {"id": "S25_coup", "chapter": 6, "start": 242.065, "dur": 11.366, "cues": [{"text": "1898年9月21日", "start": 1.8, "end": 4.025, "line": 0}, {"text": "慈禧太后宣布重新“训政”", "start": 4.185, "end": 6.222, "line": 0}, {"text": "光绪帝随后被幽禁于中南海瀛台，史称“戊戌政变”", "start": 6.382, "end": 10.306, "line": 0}]}, {"id": "S26_exile", "chapter": 6, "start": 253.431, "dur": 3.874, "cues": [{"text": "康有为、梁启超先后流亡海外", "start": 0.2, "end": 2.614, "line": 0}]}, {"id": "S27_six", "chapter": 6, "start": 257.305, "dur": 10.388, "cues": [{"text": "9月28日", "start": 0.4, "end": 1.682, "line": 0}, {"text": "谭嗣同、林旭、杨锐、刘光第、杨深秀、康广仁六人在北京菜市口遇害", "start": 1.842, "end": 6.897, "line": 0}, {"text": "史称“戊戌六君子”", "start": 7.057, "end": 8.528, "line": 0}]}, {"id": "S28_poem", "chapter": 6, "start": 267.693, "dur": 10.144, "cues": [{"text": "据梁启超记述，谭嗣同拒绝出走", "start": 0.3, "end": 2.903, "line": 0}, {"text": "并在狱中题壁写道", "start": 3.063, "end": 4.722, "line": 0}, {"text": "“我自横刀向天笑", "start": 4.982, "end": 6.453, "line": 1}, {"text": "去留肝胆两昆仑。”", "start": 6.613, "end": 8.084, "line": 1}]}, {"id": "S29_aftermath", "chapter": 6, "start": 277.837, "dur": 6.56, "cues": [{"text": "新政措施，除京师大学堂等少数几项外", "start": 0.3, "end": 3.469, "line": 0}, {"text": "几乎全部被废止", "start": 3.629, "end": 5.1, "line": 0}]}, {"id": "S30_echo", "chapter": 7, "start": 284.397, "dur": 12.053, "cues": [{"text": "戊戌变法失败了", "start": 1.6, "end": 3.07, "line": 0}, {"text": "但它推动了思想启蒙", "start": 3.43, "end": 5.278, "line": 0}, {"text": "使政治改革成为公开讨论的议题", "start": 5.438, "end": 8.23, "line": 0}, {"text": "也为中国近代教育播下了种子", "start": 8.39, "end": 10.993, "line": 0}]}, {"id": "S31_final", "chapter": 7, "start": 296.45, "dur": 10.024, "cues": [{"text": "103天，未能改变一个王朝的命运", "start": 0.4, "end": 3.569, "line": 0}, {"text": "却成为中国近代变革历程中无法绕过的一页", "start": 3.829, "end": 7.564, "line": 1}]}, {"id": "S32_credits", "chapter": 7, "start": 306.474, "dur": 11.0, "cues": []}]};
